import * as React from "react";
import { X } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { SheetSection } from "@/components/side-sheet/parts";
import { RecordSheet } from "./RecordSheet";


/**
 * Export, as a side sheet that shows what is about to leave the building.
 *
 * THE EXPORT IS THE LIST, and that is the whole idea: the file you get is the
 * rows you are looking at, narrowed by the same questions the toolbar asked.
 * Pressing Export straight from the toolbar exported that set silently, which
 * meant the one moment a reader needs to check their narrowing — the moment
 * the data goes somewhere it can no longer be corrected — was the one moment
 * the narrowing was invisible.
 *
 * THE FORMAT IS A FOOTER DECISION, beside the count and the button. It is the
 * last thing you choose and the only one that does not change what is in the
 * file, so it has no business among the narrowings above.
 *
 * THE SHEET'S CONTROLS ARE THE SCREEN'S CONTROLS. The date stepper and the
 * Filters button are the same two the toolbar carries, behaving the same way —
 * a reader who has narrowed the board has already learnt this sheet. The one
 * thing the sheet adds is the LIST OF WHAT IS ON, under them: the panel shows
 * one facet at a time and cannot answer "what am I exporting" on its own, and
 * the answer includes narrowings that are not facets at all.
 *
 * It edits the LIST'S OWN state rather than keeping a private copy: two filter
 * models that can disagree is how a reader ends up exporting one thing while
 * looking at another.
 */

export type ExportFormat = "csv" | "pdf" | "doc";

const FORMATS: { value: ExportFormat; label: string }[] = [
  { value: "csv", label: ".csv" },
  { value: "pdf", label: ".pdf" },
  { value: "doc", label: ".doc" },
];

/** A narrowing that can be taken off here, one chip per applied value. */
export interface ExportFilterRow {
  key: string;
  label: string;
  values: { value: string; onRemove: () => void }[];
  /** Takes the whole row off at once. Shown only when the row holds several. */
  onRemoveAll?: () => void;
}

/** The shelf's chip, again — same shape, because it is the same fact. */
function ValueChip({
  value,
  label,
  onRemove,
}: {
  value: string;
  label: string;
  onRemove: () => void;
}) {
  return (
    <span className="inline-flex h-7 max-w-full items-center gap-1 rounded-full bg-muted pr-1 pl-3 text-xs text-foreground">
      <span className="truncate">{value}</span>
      <button
        type="button"
        aria-label={`Remove filter ${label}: ${value}`}
        onClick={onRemove}
        className="flex size-5 shrink-0 items-center justify-center rounded-full text-muted-foreground outline-none hover:bg-foreground/10 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
      >
        <X className="size-3" />
      </button>
    </span>
  );
}

export function ExportSheet({
  open,
  onOpenChange,
  title = "Export",
  /** Plural noun for the count — "orders", "vendors". */
  noun,
  /** Its singular, for a count of one. Defaults to `noun` minus a trailing s. */
  nounOne,
  /** How many rows the current narrowing leaves. */
  count,
  /** The date control — the screen's own, the one the toolbar carries. */
  date,
  filtersControl,
  filters,
  onExport,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title?: string;
  noun: string;
  nounOne?: string;
  count: number;
  date?: React.ReactNode;
  /** The facet panel's trigger — the screen's own `ListFilters`. */
  filtersControl?: React.ReactNode;
  /** The applied narrowings, listed under the panel. */
  filters: ExportFilterRow[];
  onExport: (format: ExportFormat) => void;
}) {
  const on = filters.filter((f) => f.values.length > 0);
  const [format, setFormat] = React.useState<ExportFormat>("csv");

  return (
    <RecordSheet
      /* Controls, not a form — no step column. */
      stepNav={false}
      /* 510. Wider than the 392 the flattened calendar was squeezed into, and
         still short of the DS narrow's 560: this sheet holds controls, not a
         two-column form. */
      size="compact"
      open={open}
      onOpenChange={onOpenChange}
      mode="create"
      editTitle={title}
      createTitle={title}
      createAction="Export"
      /* NO CANCEL. This sheet commits nothing on its way through — the
         narrowings it edits are the list's own and are already visible behind
         it — so there is nothing for Cancel to undo that Close does not do, and
         a button promising to undo what it cannot is worse than no button. */
      showCancel={false}
      /* THE COUNT KEEPS THE LEFT. It is the number the reader is deciding
         about, and in the body it scrolled away from the decision. */
      footerAside={
        <span className="text-sm text-foreground">
          <span className="font-medium tabular-nums">{count}</span>{" "}
          <span className="text-muted-foreground">
            {count === 1 ? (nounOne ?? noun.replace(/s$/, "")) : noun}
          </span>
        </span>
      }
      /* THE FORMAT TRAVELS WITH THE BUTTON, 12px off it. It is part of the act
         — "export, as this" — not a fact about the list, and out on the left
         beside the count it read as one, half a sheet away from the control it
         qualifies. */
      footerPrimary={
        <div className="flex items-center gap-3">
          <Select
            value={format}
            onValueChange={(v) => setFormat(v as ExportFormat)}
          >
            <SelectTrigger size="sm" className="w-[92px]" aria-label="File format">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {FORMATS.map((f) => (
                <SelectItem key={f.value} value={f.value}>
                  {f.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Button disabled={count === 0} onClick={() => onExport(format)}>
            Export
          </Button>
        </div>
      }
      /* `footerPrimary` carries its own disabled state, so `canSubmit` has
         nothing to gate. `onSubmit` stays wired for the Enter key. */
      onSubmit={() => count > 0 && onExport(format)}
    >
      {/* PLAIN SECTIONS, NOT CARDS. A card draws an edge to say where a block
          starts and ends; each of these is one control under one heading, and a
          box around it was a third edge inside a sheet that is itself a
          bordered surface. The heading and the 40px between sections carry
          it. */}
      {/* THE DATE IS ONE LINE, UNDER ITS HEADING. The control prints the window
          it is on and opens the rest on click, so there is nothing for a second
          row to hold — and the sheet's subject is the filters below, which a
          laid-out calendar was burying. It takes the full width like every
          other block here rather than perching on the heading's right. */}
      {date && (
        <SheetSection variant="plain" title="Date">
          {date}
        </SheetSection>
      )}

      <SheetSection variant="plain" title="Filters">
        {/* THE CONTROL AND WHAT IT PRODUCED ARE ONE UNIT, 12px apart. The
            section's 16px belongs to heading→content; inside the content the
            button and the list it filled are the same thought, and the 48 that
            used to sit here read as a second section with no heading. */}
        <div className="flex flex-col gap-3">
          {filtersControl}

          {/* 24px BETWEEN GROUPS, now spent as 12 / rule / 12 rather than as
              one gap. Several rows wrap onto two lines of chips, and a gap
              alone could not say whether a second line belonged to the row
              above it or the one below — the rule says it. */}
          {on.length > 0 && (
            <div className="flex flex-col gap-3">
              {on.map((f, i) => (
                /* THE RULE RUNS THE WHOLE WIDTH, label column included: the
                   row is one thing — a question and its answer — and a line
                   that started at the chips cut the row in half rather than
                   separating it from the next. Not after the last row: there is
                   nothing below to separate it from. */
                <div
                  key={f.key}
                  className={cn(
                    "flex items-start gap-3",
                    i < on.length - 1 && "border-b border-border pb-3"
                  )}
                >
                  <span className="w-[140px] shrink-0 pt-0.5 text-xs text-muted-foreground">
                    {f.label}
                  </span>
                  <div className="flex min-w-0 flex-1 flex-wrap items-center gap-1.5">
                    {f.values.map((v) => (
                      <ValueChip
                        key={v.value}
                        value={v.value}
                        label={f.label}
                        onRemove={v.onRemove}
                      />
                    ))}
                    {/* CLEAR THE ROW, only where there is a row to clear. On a
                        single value it would be a second control doing what the
                        chip's own X already does. */}
                    {f.values.length > 1 && f.onRemoveAll && (
                      <Button
                        variant="ghost"
                        size="xs"
                        className="h-5 px-1 text-[11px] text-muted-foreground"
                        onClick={f.onRemoveAll}
                      >
                        Clear
                      </Button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </SheetSection>
    </RecordSheet>
  );
}

import * as React from "react";
import { cn } from "@/lib/utils";
import { ChevronLeft, ChevronRight, CircleCheck, Info } from "lucide-react";

/**
 * THE PENDING STRIP — what a sheet's next act is still waiting on.
 *
 * SHARED, BECAUSE THE SECOND SHEET TO NEED IT IS THE PROMOTION SIGNAL. It was
 * written twice — once for the 3PL order and once for the service order — and
 * two copies of something this fiddly would have drifted in whichever half
 * gets opened less.
 *
 * It goes in `RecordSheet`'s `footerBanner`: the reason a primary is dead
 * belongs beside it, and beside it there is room for a clause, not for a list.
 * Each caller supplies its own items and its own section ids.
 */

export interface PendingItem {
  key: string;
  /** The INSTRUCTION — "Choose a customer", not "Customer". */
  label: string;
  /** The `id` of the section this item is about. Omitted = not pressable. */
  target?: string;
}

/**
 * SEND THE READER TO THE SECTION, and say which one it was.
 *
 * A strip that names a missing field and cannot take you to it is a label for
 * a hunt. The press scrolls the section into view and then blinks its outline
 * — because after a scroll the eye is on the MOVEMENT, not on the thing that
 * moved, and "it is this one" is a different statement from "here is some of
 * the form".
 *
 * ONCE, AND IT LEAVES NO TRACE (Pavan, 2026-09-22 — it was twice). Two flashes
 * is a thing asking to be watched; one is a thing pointing at itself and then
 * getting out of the way, and the reader is already looking because the scroll
 * took them there. Three times reads as an error, and a ring that stays is a
 * state — nothing about the record changed, so nothing about it should still
 * look different in a second.
 */
export function attend(id: string) {
  const el = document.getElementById(id);
  if (!el) return;

  /* SCROLL THE CONTAINER, NOT THE ELEMENT. `scrollIntoView` picks its own
     ancestor and hands the animation to the browser. Finding the scrollport
     and setting its offset is deterministic. */
  let port: HTMLElement | null = el.parentElement;
  while (port && port.scrollHeight <= port.clientHeight + 4) {
    port = port.parentElement;
  }
  if (!port) return;
  /* 12px of air above the section, so it does not sit flush against the header
     and read as clipped. */
  const top =
    port.scrollTop +
    el.getBoundingClientRect().top -
    port.getBoundingClientRect().top -
    12;

  /* ANIMATED BY HAND, because `behavior: "smooth"` does not survive in here.
     MEASURED in the running sheet: an instant scroll to 400 lands at 400; the
     same call with `smooth` lands at 0 — the sheet's scroll lock cancels the
     browser's animation the frame after it starts. The rAF loop is not
     decoration: without it the section either does not move or teleports, and
     the travel is what tells the reader this is the same sheet they were
     already in rather than a new screen. */
  const from = port.scrollTop;
  const distance = top - from;
  const started = performance.now();
  const DURATION = 320;
  const scroller = port;
  const step = (now: number) => {
    const t = Math.min((now - started) / DURATION, 1);
    /* ease-out cubic — fast away, slow into place, which is what makes an
       arrival read as an arrival. */
    scroller.scrollTop = from + distance * (1 - Math.pow(1 - t, 3));
    if (t < 1) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);

  /* NO FOCUS MOVE. Focusing the section, or a control inside it, was tried and
     dropped: inside a focus-trapped sheet the trap restores the scroll position
     of whatever it considers focused, which fights the travel. The blink is
     what says "this one", and focus stays on the strip — which is where the
     reader presses next if more than one item is outstanding.
     KEYBOARD GAP, KNOWN: a reader who presses this with the keyboard is shown
     the section but still has to Tab to it. */

  /* THE BLINK WAITS FOR THE SCROLL. Flashing a section that is still
     travelling spends the whole animation off screen. */
  window.setTimeout(() => blink(id), 320);
}

/** How long `blink` takes, start to finish — for anything sequencing after it. */
export const BLINK_MS = 800;

/**
 * THE FLASH ON ITS OWN, WITHOUT THE TRAVEL.
 *
 * FOR A SECOND, NARROWER "THIS ONE". After a section has been brought into
 * view and named, the thing actually worth reading inside it can be named
 * too — the Pricing unit, then the vendor's own column. Two statements, not
 * one longer one: "here" and then "this part of here". They must not overlap,
 * or the second reads as the first still going.
 */
export function blink(id: string) {
  const el = document.getElementById(id);
  if (!el) return;
  el.classList.remove("fp-attention");
  /* Re-adding in the same frame does not restart a CSS animation; the reflow
     between the two is what does. */
  void el.offsetWidth;
  el.classList.add("fp-attention");
  window.setTimeout(() => el.classList.remove("fp-attention"), BLINK_MS);
}

/**
 * THE SAME FLASH, ACROSS SOMETHING THAT IS NOT ONE BOX.
 *
 * A column of a grid is a stack of separate cells: an outline round each of
 * them is a ladder, not a column. Every cell that belongs to the thing carries
 * `data-blink="<name>"`, and they flash a FILL together — which reads as the
 * one unit it is. (Pavan, 2026-09-22 — "blink should happen through this whole
 * unit".)
 */
export function blinkGroup(name: string) {
  const els = document.querySelectorAll<HTMLElement>(`[data-blink="${name}"]`);
  els.forEach((el) => {
    el.classList.remove("fp-attention-fill");
    /* Re-adding in the same frame does not restart a CSS animation; the reflow
       between the two is what does. */
    void el.offsetWidth;
    el.classList.add("fp-attention-fill");
    window.setTimeout(() => el.classList.remove("fp-attention-fill"), BLINK_MS);
  });
}

/**
 * One outstanding item at a time, with a counter and a way to step through
 * them, so three missing fields cost one line rather than three.
 *
 * THE WORD "PENDING" DOES NOT MOVE. It is the strip's subject and it is true
 * of every item under it; stepping swaps only the item. A label that changed
 * with the content would make the reader re-read what KIND of line this is on
 * every press.
 *
 * WHEN NOTHING IS OUTSTANDING IT SAYS SO, in the success channel, rather than
 * disappearing: an empty strip and a satisfied one are different states.
 */
export function PendingStrip({
  pending,
  /** What the strip says when the list is empty. */
  clearLabel = "Everything this record needs is filled in",
  tone = "neutral",
}: {
  pending: PendingItem[];
  clearLabel?: string;
  /**
   * `caution` once the strip is raised by pressing the primary with
   * something missing (2026-10-05) — it is the answer to a press and has to
   * be noticed. `neutral` (grey) where it simply stands on the sheet.
   */
  tone?: "neutral" | "caution";
}) {
  const [at, setAt] = React.useState(0);
  /* The list shortens as items are cleared, so the cursor has to be pulled
     back with it rather than pointing past the end. */
  const i = Math.min(at, Math.max(pending.length - 1, 0));
  React.useEffect(() => {
    if (at > pending.length - 1) setAt(Math.max(pending.length - 1, 0));
  }, [at, pending.length]);

  if (pending.length === 0) {
    return (
      <div className="flex items-center gap-2 text-sm text-fp-banner-accent-success">
        <CircleCheck className="size-4 shrink-0" />
        {clearLabel}
      </div>
    );
  }

  const step = pending[i];
  const chevron =
    "rounded-sm p-0.5 text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 disabled:pointer-events-none disabled:opacity-30";

  return (
    /* IN THE STEP COLUMN (a narrow `@container`) the strip is two rows
       (Pavan, 2026-10-05): "Pending" on the left with the stepper on the
       right, and the item itself underneath, wrapping rather than truncating.
       No icon there. The first span dissolves (`contents`) so its pieces can
       be laid out against the counter. In the full-width footer band nothing
       changes. GREY, not caution orange (Pavan, 2026-10-05): what is left to
       do is information, not an alarm. */
    <div className="flex items-center justify-between gap-3 @max-[20rem]:flex-wrap @max-[20rem]:gap-y-1">
      <span
        className={cn(
          "flex min-w-0 items-center gap-2 text-sm @max-[20rem]:contents",
          tone === "caution" ? "text-fp-banner-accent-caution" : "text-muted-foreground"
        )}
      >
        <Info className="size-4 shrink-0 @max-[20rem]:hidden" />
        <span className="shrink-0 font-medium @max-[20rem]:order-1">Pending</span>
        {step.target ? (
          <button
            type="button"
            onClick={() => attend(step.target!)}
            className="min-w-0 truncate rounded-sm text-left @max-[20rem]:order-3 @max-[20rem]:basis-full @max-[20rem]:whitespace-normal underline decoration-current/40 underline-offset-4 outline-none transition-[text-decoration-color] hover:decoration-current focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            {step.label}
          </button>
        ) : (
          <span className="truncate @max-[20rem]:order-3 @max-[20rem]:basis-full @max-[20rem]:whitespace-normal">{step.label}</span>
        )}
      </span>
      <span className="flex shrink-0 items-center gap-0.5 text-xs tabular-nums text-muted-foreground @max-[20rem]:order-2">
        <button
          type="button"
          aria-label="Previous pending item"
          disabled={i === 0}
          onClick={() => setAt(i - 1)}
          className={chevron}
        >
          <ChevronLeft className="size-3.5" />
        </button>
        {i + 1} of {pending.length}
        <button
          type="button"
          aria-label="Next pending item"
          disabled={i >= pending.length - 1}
          onClick={() => setAt(i + 1)}
          className={chevron}
        >
          <ChevronRight className="size-3.5" />
        </button>
      </span>
    </div>
  );
}

import * as React from "react";
import { Check, Loader2, X } from "lucide-react";
import { StatusChip, type StatusTone } from "@/components/ui/status-chip";
import type { PillColor } from "@/components/ui/pill";
import { cn } from "@/lib/utils";
import { QuietPattern } from "@/components/ui/quiet-pattern";
import { Button } from "@/components/ui/button";
import { Sheet, SheetClose, SheetContent, SheetTitle } from "@/components/ui/sheet";
import { SteppedFormBody } from "@/components/side-sheet/form-steps";
import { FormStepsContext } from "@/components/side-sheet/form-steps-context";
import { PendingStrip, attend, type PendingItem } from "./PendingStrip";

/**
 * Side-sheet shell for a single record — edit or create.
 *
 * Chrome is the DS's, taken from `side-sheet/SheetNarrow.tsx` (Figma "Side
 * Sheet" 27610:58293) and matched to the Fuel Orders order sheet so all three
 * sheets are identical where they should be:
 *   • SheetContent  w-560 (DS `narrow`), gap-0 p-0
 *   • header        border-b, p-4, items-start justify-between gap-4
 *   • body          p-4, flex-col gap-10   ← 40px between groups
 *   • footer        border-t, p-4, items-center justify-end gap-3
 *
 * The 40px group rhythm is the same deliberate override the order sheet
 * documents: these sheets carry far more fields than the DS reference, and at
 * the DS's gap-7 the groups stopped reading as groups. The 1:2 ratio against
 * SheetSection's gap-5 is preserved, so only the scale moved.
 *
 * CREATE AND EDIT ARE THE SAME SHEET. `mode="create"` swaps the title for the
 * create label and the submit button with it, and the caller seeds a blank
 * draft. One layout to learn, and no separate create form to drift.
 *
 * DS FOLLOW-UP: nothing here is screen-specific. This belongs beside
 * `side-sheet/` in the DS, with the order sheet moved onto it too.
 */
/**
 * A COLUMN'S COMFORTABLE WIDTH, by what it holds (Pavan, 2026-10-15). A
 * table-led sheet adds these up to find its width; one number per kind, so
 * the same column is the same width in every sheet.
 */
export const CELL = {
  /* TIGHTENED (Pavan, 2026-10-15): asset and product names are short, a
     quantity is at most six digits — the columns, and so the sheet, are only
     as wide as that. */
  /** A row's select checkbox, an expand chevron. */
  check: 44,
  /** "Top off" and other labelled checkboxes. */
  flag: 72,
  /** Top off — its label and the select-all, just before the quantity (DS ui §10i). */
  topOff: 104,
  /** A tank's level reading — gauge and % (portal, 2026-10-17). */
  level: 150,
  /** A tank monitor's battery. */
  battery: 100,
  /** The row's own thing — an asset, a product, a partner, a document. */
  name: 200,
  /** A pick from a short list — type, unit, condition, terminal. */
  pick: 160,
  /** A quantity or an amount, with its unit — six digits. */
  number: 110,
  date: 140,
  status: 140,
  /** Free text — a fault, a note. */
  text: 240,
  /** The row bin / a row menu. */
  bin: 52,
} as const;

export interface SheetFit {
  /** Each table's columns, as `CELL` widths; the widest table decides. */
  tables: number[][];
  /** The 340px right rail (summary · activity) beside the tables. */
  rail?: boolean;
}

/*
  THE PATTERN UNDER A SHORT FORM (Pavan, 2026-10-16). When what the sheet
  holds takes HALF the visible height or less, the DS quiet pattern fills
  the rest — to the body's left, right and bottom edges. Taller than that,
  there is no pattern and no space kept for it. Measured live, so a form
  that grows as it is filled loses the pattern when it passes half.
*/
const BODY_GAP = 40;
const BODY_PAD = 16;
function SheetPattern() {
  const ref = React.useRef<HTMLDivElement>(null);
  const [shown, setShown] = React.useState(false);
  React.useLayoutEffect(() => {
    const el = ref.current;
    const body = el?.parentElement;
    if (!el || !body) return;
    const measure = () => {
      const visible = body.clientHeight;
      if (!visible) return;
      const top = el.getBoundingClientRect().top - body.getBoundingClientRect().top + body.scrollTop;
      /* Where the content ends — the pattern's own gap taken out. */
      const content = top - BODY_PAD - (el.dataset.shown === "true" ? BODY_GAP : 0);
      setShown(content <= visible / 2);
    };
    const ro = new ResizeObserver(measure);
    ro.observe(body);
    for (const c of Array.from(body.children)) if (c !== el) ro.observe(c);
    const mo = new MutationObserver(() => {
      for (const c of Array.from(body.children)) if (c !== el) ro.observe(c);
      measure();
    });
    mo.observe(body, { childList: true });
    measure();
    return () => {
      ro.disconnect();
      mo.disconnect();
    };
  }, []);
  return (
    <div
      ref={ref}
      data-shown={shown}
      aria-hidden
      /* Hidden, it takes no room: zero height, and the gap above canceled. */
      className={cn(shown ? "-mx-4 -mb-4 flex min-h-24 flex-1" : "-mt-10 h-0 overflow-hidden")}
    >
      {shown && <QuietPattern className="flex-1" />}
    </div>
  );
}

/**
 * THE SHEET UNDERNEATH, for a sheet opened over it (Pavan, 2026-10-15). Now
 * that widths follow content, two sheets can be the same width, and the top
 * one would cover the other exactly — reading as the SAME sheet having
 * changed. A level-2 sheet is therefore never wider than the one beneath it
 * less the 56px gap, so a strip of it always shows.
 */
const ParentSheetWidth = React.createContext<number | null>(null);

/** BODY PADDING (16 + 16) AND THE TABLE BOX'S BORDERS. */
const FIT_PAD = 34;
const RAIL = 340 + 24;
export const FORM_WIDTH = 600;
export const DATA_WIDTH = 1200;
/** A data-intensive sheet's field grid — three across, at 1200. */
export const DATA_FIELDS = "grid grid-cols-3 gap-4";

/**
 * The width a table-led sheet takes. THE FORM SIDE IS NEVER NARROWER THAN A
 * 600 FORM'S (Pavan, 2026-10-15): beside a rail, small tables still leave the
 * fields two across at a readable width; the rail adds its own 364.
 */
export function fitWidth(fit: SheetFit): number {
  const widest = Math.max(0, ...fit.tables.map((t) => t.reduce((n, w) => n + w, 0)));
  return Math.max(FORM_WIDTH - FIT_PAD, widest) + FIT_PAD + (fit.rail ? RAIL : 0);
}

export interface RecordSheetProps {
  /**
   * THE WIDTH FOLLOWS WHAT IS IN THE SHEET (Pavan, 2026-10-15 — replaces the
   * fixed 560 / 864 / 1120 tiers and the 756 creation floor). A sheet sized
   * for more than it holds reads as empty.
   *
   *   `form`     600 — fields and text, no table. The default.
   *   `compact`  510 — CONTROLS rather than a form (a facet list).
   *   `data`     1200 at least — a DATA-INTENSIVE record's detail: many
   *              fields and several related-records tables (a 3PL customer,
   *              vendor, product, rental asset). Fields go three across
   *              (`DATA_FIELDS`); with `fit`, the wider of the two. Pavan,
   *              2026-10-15: "cramped … should have more width so that
   *              information can be easily consumed".
   *   `full`     the viewport less the gap — no form uses it now: every
   *              order sheet fits its tables (Pavan, 2026-10-15). Kept for a
   *              sheet showing its step column.
   *
   * A sheet that carries TABLES passes `fit` instead, and is as wide as its
   * widest table's columns at a comfortable width (`CELL`), plus the body's
   * padding, plus the 340px rail and its gap when it has one — never under
   * 600. Per step: a stepped sheet passes the tables of the step on show.
   *
   * THE GAP IS 56px AND IT IS THE ONE CONSTANT. Every width is clamped to
   * `100vw - 56px`, so no sheet reaches the edge or overflows a small screen.
   * A sheet opened OVER another one takes that gap TWICE — see `level`.
   */
  size?: "compact" | "form" | "data" | "full";
  /** Width from the sheet's tables — see `size` and `fitWidth`. */
  fit?: SheetFit;
  /**
   * HOW DEEP IN THE STACK THIS SHEET IS. `2` is a sheet opened OVER another
   * one — the invitation over an order, a partner's quote over an order.
   *
   * IT TAKES A SECOND GAP (Pavan, 2026-09-22). The 56px is what tells a reader
   * a sheet is over something; a second sheet at the same inset covers the
   * first exactly and reads as the SAME sheet having changed its contents.
   * 112px leaves a 56px strip of the sheet underneath showing, which says
   * "there is one of these behind this one" in the only language the stack
   * has.
   */
  level?: 1 | 2;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  mode: "edit" | "create";
  /** Header title when editing, e.g. `Order #: 6104420`. */
  editTitle: string;
  /** Header title when creating, e.g. `Create Asset Order`. */
  createTitle: string;
  /** Submit label when editing. Defaults to the DS's `Save Changes`. */
  /**
   * THE EDIT-MODE PRIMARY. "Confirm", not "Save Changes" — autosave is the
   * default now, so by the time anybody looks at the footer the change is
   * already written and a Save would be claiming credit for work already
   * done. What is left to do is agree that the record is right.
   *
   * It is a per-sheet word: a footer that commits the record to a NEXT ACT
   * should say that act instead. Changed 2026-09-22.
   */
  editAction?: string;
  /** Submit label when creating — usually the same words as `createTitle`. */
  createAction: string;
  /** Rendered beside the title, e.g. a StatusChip. */
  headerAside?: React.ReactNode;
  /**
   * A second line under the title, inside the sticky header.
   *
   * For a fact about the record that must not scroll away — "this partner
   * holds the order" is the answer to a question the reader has while they are
   * looking at any part of the sheet, and at the bottom of a long step it was
   * only true where nobody was looking.
   */
  headerSubtitle?: React.ReactNode;
  /**
   * DRAFT AUTOSAVE, SAID OUT LOUD.
   *
   * A sheet that keeps a draft has to tell the reader it is keeping it, or
   * they behave as though it does not — they finish fields they meant to come
   * back to, and they hesitate to close. Three states and nothing else:
   * `saving` while a change settles, `saved` once it has, and `idle` before
   * anything has been typed, which shows nothing at all because there is
   * nothing to reassure anybody about yet.
   *
   * It sits by the TITLE, not the footer: it is a statement about the record,
   * not a control, and beside Save it would read as a second button. The
   * caller passes it through `DraftStatusChip`, which on a Draft swaps the
   * chip for the line "Draft saved" rather than showing both.
   */
  /**
   * The ··· at the right of the header, between the history icon and Close.
   * For acts ON the record that are not part of filling it in — deleting it.
   */
  headerMenu?: React.ReactNode;
  /**
   * Cancel in the footer. OFF on a sheet that autosaves its draft: "Cancel"
   * promises to undo, and a sheet that has already kept everything typed
   * cannot keep that promise. Close is the honest exit there.
   */
  showCancel?: boolean;
  /**
   * Controls at the far right of the header, left of Close.
   *
   * For things that OPEN something rather than change the record — a history,
   * a preview, a related list. They live in the header because they are not
   * part of the form and must not scroll away with it, and left of Close
   * because Close is the last thing on that edge in every sheet.
   */
  headerActions?: React.ReactNode;
  /**
   * A step strip under the header — `SheetSteps`. It sits above the body and
   * outside its scroll, because which step you are on is not something that
   * should be able to scroll away from you.
   */
  steps?: React.ReactNode;
  /** Disable submit while the draft is incomplete. */
  canSubmit?: boolean;
  /**
   * WHAT THE DEFAULT PRIMARY IS WAITING ON (Pavan, 2026-10-07 — G25). Given,
   * the default primary never goes dead: it stays pressable, and a press while
   * anything is listed (or `canSubmit` is false) raises the pending strip above
   * the footer and takes the reader to the first gap — the 3PL order / Quote
   * pattern. Ignored when `footerPrimary` replaces the button, and the caller's
   * own `footerBanner` wins over the strip.
   */
  pending?: PendingItem[];
  /**
   * Replaces the footer's primary button — and `null` removes it entirely.
   *
   * THE FOOTER'S RIGHT EDGE IS "THE MAIN THING TO DO HERE", and on a
   * multi-step sheet that is not the same act on every step. A step whose work
   * ends in a decision — accept this price — has a better claim to that slot
   * than a generic Save, and a step with nothing left to commit has no claim
   * at all. Omit the prop for the default Save/Create.
   */
  footerPrimary?: React.ReactNode;
  /**
   * Controls that ride in the footer, left of Cancel/Submit. For decisions
   * taken at the moment of committing rather than while filling the form —
   * they stay in view no matter how far the body has scrolled.
   */
  footerAside?: React.ReactNode;
  onSubmit: () => void;
  /**
   * A FIXED STRIP DIRECTLY ABOVE THE FOOTER, spanning the sheet.
   *
   * For what the footer's act is waiting on. The reason a primary is disabled
   * belongs beside it, and beside it there is room for a clause — not for a
   * list. This is where a sheet says what is still outstanding, in the one
   * place that does not scroll away from the button it is about.
   */
  footerBanner?: React.ReactNode;
  /** Classes for the banner while it sits under a stepped form's column. */
  footerBannerClassName?: string;
  /** A control on the step column's "Step N of M" row — form settings. */
  stepsAction?: React.ReactNode;
  /**
   * THE FORM AS STEPS (Pavan, 2026-10-05) — a column on the left listing the
   * form's steps, the form as one long scroll beside it, and the pending strip
   * at the foot of that column instead of above the footer. On by default for
   * every first-level sheet; the sheet takes the full width while the column
   * shows. The column only shows when there are two or more steps — see
   * `components/side-sheet/form-steps`.
   */
  stepNav?: boolean;
  /**
   * The step column itself. Off = the stepped form without the column on the
   * left (Pavan, 2026-10-06 — removed from the 3PL order sheets, archived in
   * docs/ds/ui/archive/step-column.md). OFF IN EVERY MODULE since 2026-10-07
   * (Pavan): pass `true` to bring it back on one sheet.
   */
  stepColumn?: boolean;
  children: React.ReactNode;
}

/**
 * Watch a draft and report whether it has been kept.
 *
 * ONE HOOK, SO EVERY DRAFT SHEET SAYS THE SAME THING. A sheet that autosaves
 * silently is a sheet people do not trust with unfinished work: they either
 * finish fields they meant to return to, or they hesitate to close. The
 * feedback is the feature.
 *
 * `saving` for 500ms after a change settles, then `saved`. It stays `idle`
 * until the FIRST change, because before anyone has typed there is nothing to
 * reassure them about — and a sheet that opens saying "Saved" is claiming to
 * have done something it has not.
 */
export function useDraftSaveState(draft: unknown, enabled = true) {
  const [state, setState] = React.useState<"idle" | "saving" | "saved">("idle");
  const serialised = React.useMemo(() => JSON.stringify(draft ?? null), [draft]);
  const first = React.useRef<string | null>(null);

  React.useEffect(() => {
    if (!enabled) {
      first.current = null;
      setState("idle");
      return undefined;
    }
    /* A SHEET FILLS ITS DRAFT ONE RENDER AFTER IT OPENS, so the first value
       seen here is `null` and the second is the untouched form. Treating that
       as an edit made every sheet open saying "Saved" — claiming to have kept
       something nobody had typed. The baseline is the first REAL draft. */
    if (draft === null || draft === undefined) return undefined;
    if (first.current === null) {
      first.current = serialised;
      return undefined;
    }
    if (serialised === first.current) return undefined;
    setState("saving");
    const t = window.setTimeout(() => setState("saved"), 500);
    return () => window.clearTimeout(t);
  }, [serialised, enabled, draft]);

  return state;
}

/**
 * The record's state in the header: what it IS, and whether the draft is kept.
 *
 * ONE THING WHEN THEY ARE THE SAME WORD. On a Draft, a status dot, the word
 * "Draft", a separator dot and the word "Saved" were four marks for one fact.
 * Once typing starts the chip gives way to plain text — "Draft saving…", then
 * "Draft saved" — which carries the status and the reassurance in one line.
 *
 * TWO WHEN THEY ARE NOT. An Assigned order being edited still has a status
 * worth seeing, and "Assigned saved" is not a sentence — so the status keeps
 * its chip and the save note sits beside it. The word stays "Draft" either
 * way, because what is kept is the draft of the edit, not the order.
 */
export function DraftStatusChip({
  tone,
  color,
  label,
  saveState = "idle",
  showStatus = true,
}: {
  tone: StatusTone;
  /* A STAGE COLOUR THE USER CHOSE (Pavan, 2026-10-09) — Sales stages keep
     the colour set in Sales Settings, in the header as in the table. */
  color?: PillColor | null;
  label: string;
  saveState?: "idle" | "saving" | "saved";
  /**
   * False drops the status chip and keeps only the save note — for a sheet
   * whose stage is already shown on its own track (Pavan, 2026-10-05).
   */
  showStatus?: boolean;
}) {
  const note =
    saveState === "saving" ? (
      <>
        <Loader2 className="size-3 animate-spin" />
        Draft saving…
      </>
    ) : (
      <>
        <Check className="size-3" />
        Draft saved
      </>
    );

  if (!showStatus) {
    if (saveState === "idle") return null;
    return (
      <span
        className="flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground"
        aria-live="polite"
      >
        {note}
      </span>
    );
  }

  if (saveState === "idle") {
    return (
      <StatusChip tone={tone} color={color} variant="soft">
        {label}
      </StatusChip>
    );
  }

  /* A DRAFT SAYS IT ONCE. "Draft saved" already contains the status, so the
     chip — its dot, its fill, its own word "Draft" — would be saying the same
     thing a second and third time. Plain text, one mark, one meaning. */
  if (label.toLowerCase() === "draft") {
    return (
      <span
        className="flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground"
        aria-live="polite"
      >
        {note}
      </span>
    );
  }

  /* NOT A DRAFT, so two things are true at once. An Assigned order still has a
     status worth seeing, and "Assigned saved" is not a sentence — the status
     keeps its chip and the save note sits beside it. The word stays "Draft"
     because what is kept is the draft of the edit, not the order. */
  return (
    <span className="flex items-center gap-2">
      <StatusChip tone={tone} color={color} variant="soft">
        {label}
      </StatusChip>
      <span
        className="flex shrink-0 items-center gap-1.5 text-xs text-muted-foreground"
        aria-live="polite"
      >
        {note}
      </span>
    </span>
  );
}

export function RecordSheet({
  size = "form",
  fit,
  level = 1,
  open,
  onOpenChange,
  mode,
  editTitle,
  createTitle,
  editAction = "Confirm",
  createAction,
  headerAside,
  headerSubtitle,
  headerActions,
  headerMenu,
  showCancel = true,
  steps,
  canSubmit = true,
  pending,
  footerPrimary,
  footerAside,
  onSubmit,
  footerBanner,
  footerBannerClassName,
  stepsAction,
  stepNav,
  stepColumn = false,
  children,
}: RecordSheetProps) {
  const creating = mode === "create";
  const stepped = stepNav ?? level !== 2;
  const [navOn, setNavOn] = React.useState(false);
  const navShown = stepped && navOn;
  /* FULL WIDTH WHILE THE STEP COLUMN SHOWS (Pavan, 2026-10-05). */
  const fills = size === "full" || navShown;
  const parentWidth = React.useContext(ParentSheetWidth);
  const own =
    size === "data"
      ? Math.max(DATA_WIDTH, fit ? fitWidth(fit) : 0)
      : fit
        ? fitWidth(fit)
        : size === "compact"
          ? 510
          : FORM_WIDTH;
  const width = level === 2 && parentWidth !== null ? Math.min(own, parentWidth - 56) : own;
  /* WHY (Pavan, 2026-10-07). A dead primary says why on press (G25): the
     strip is raised by the press, not shown up front, and drops on close. */
  const [pendingRaised, setPendingRaised] = React.useState(false);
  React.useEffect(() => {
    if (!open) setPendingRaised(false);
  }, [open]);
  const saysWhy = pending !== undefined;
  const notReady = !canSubmit || (pending?.length ?? 0) > 0;
  const banner =
    footerBanner ??
    (saysWhy && pendingRaised ? <PendingStrip tone="caution" pending={pending} /> : undefined);
  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        showCloseButton={false}
        /* THE GAP IS A VARIABLE, so one set of classes serves both levels. A
           second-level sheet takes 112 — the constant, twice — and the strip
           of the sheet beneath it is what says it is second. */
        style={
          {
            "--fp-sheet-gap": level === 2 ? "112px" : "56px",
            /* SCALED IN THE WCAG MODES — wider text, wider sheet (§10n). */
            "--fp-sheet-w": `calc(${width}px * var(--fp-scale, 1))`,
          } as React.CSSProperties
        }
        className={cn(
          "gap-0 p-0",
          fills
            ? /* FULL — the intense forms, and any sheet showing its step column. */
              "w-[calc(var(--fp-vw)-var(--fp-sheet-gap))] sm:max-w-[calc(var(--fp-vw)-var(--fp-sheet-gap))]"
            : /* THE CONTENT'S WIDTH, clamped by the gap (`--fp-sheet-w`). */
              "w-[min(var(--fp-sheet-w),calc(var(--fp-vw)-var(--fp-sheet-gap)))] sm:max-w-[min(var(--fp-sheet-w),calc(var(--fp-vw)-var(--fp-sheet-gap)))]"
        )}
      >
        <div className="flex items-start justify-between gap-4 border-b border-border p-4">
          <div className="flex min-w-0 flex-col gap-1">
            <div className="flex items-center gap-2.5">
              <SheetTitle className="text-base">
                {creating ? createTitle : editTitle}
              </SheetTitle>
              {headerAside}
            </div>
            {headerSubtitle}
          </div>
          <div className="flex shrink-0 items-center gap-1">
            {headerActions}
            {headerMenu}
            <SheetClose className="rounded-sm p-1 text-muted-foreground opacity-70 outline-none transition-opacity hover:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50">
              <X className="size-4" />
              <span className="sr-only">Close</span>
            </SheetClose>
          </div>
        </div>

        {/* ACROSS THE SHEET only without a step column; with one, the band
            starts where the form starts (Pavan, 2026-10-05). */}
        {steps && !navShown && (
          /* NO RULE UNDER THE STEPS (Pavan, 2026-10-16) — the strip keeps the
             sheet's own white, and the form scrolls under it. */
          <div className="shrink-0 bg-popover px-4">{steps}</div>
        )}

        {stepped ? (
          <SteppedFormBody
            footer={navShown ? banner : undefined}
            footerClassName={footerBannerClassName}
            top={navShown ? steps : undefined}
            onShownChange={setNavOn}
            stepsAction={stepsAction}
            hideColumn={!stepColumn}
          >
            <ParentSheetWidth.Provider value={fills ? 99999 : width}>{children}</ParentSheetWidth.Provider>
            <SheetPattern />
          </SteppedFormBody>
        ) : (
          <FormStepsContext.Provider value={false}>
            <div className="flex min-h-0 flex-1 flex-col gap-10 overflow-auto p-4">
              <ParentSheetWidth.Provider value={fills ? 99999 : width}>{children}</ParentSheetWidth.Provider>
            <SheetPattern />
            </div>
          </FormStepsContext.Provider>
        )}

        {banner && !navShown && (
          /* ABOVE THE FOOTER AND OUTSIDE THE SCROLL — the same reason the
             stage bar sits under the header: a strip that describes the
             footer's button has to be visible whenever the button is. */
          <div className="shrink-0 border-t border-border px-4 py-2.5">
            {banner}
          </div>
        )}

        <div className="flex shrink-0 flex-wrap items-center justify-between gap-3 border-t border-border p-4">
          <div className="flex flex-wrap items-center gap-x-8 gap-y-2">
            {footerAside}
          </div>
          <div className="flex items-center gap-3">
          {showCancel && (
            <Button variant="outline" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
          )}
          {/* `undefined` = the default Save/Create; anything else replaces it,
              and `null` leaves the slot empty on a step with nothing to
              commit. */}
          {footerPrimary !== undefined ? (
            footerPrimary
          ) : (
            /* WHY (Pavan, 2026-10-07). With `pending` the button is never
               disabled — a press while not ready names the gap (G25). Without
               it, the old `disabled` stays so no caller changes unasked. */
            <Button
              disabled={!saysWhy && !canSubmit}
              onClick={() => {
                if (saysWhy && notReady) {
                  setPendingRaised(true);
                  const first = pending?.find((p) => p.target);
                  if (first?.target) attend(first.target);
                  return;
                }
                onSubmit();
                onOpenChange(false);
              }}
            >
              {creating ? createAction : editAction}
            </Button>
          )}
          </div>
        </div>
      </SheetContent>
    </Sheet>
  );
}

import * as React from "react";

/* The shared state behind `form-steps.tsx`, kept apart so that file exports only components. */

/** True inside a stepped sheet's form. */
export const FormStepsContext = React.createContext(false);
/** True inside a step, so the sections in it do not become steps too. */
export const InsideFormStepContext = React.createContext(false);

/** The attributes that make an element a step the list can find. */
export function formStepAttrs(label: string) {
  return { "data-form-step": label };
}

/**
 * The classes a step's own element takes: room for the landing blink's fill,
 * pulled back out so the fields stay where they were.
 */
export const FORM_STEP_CLASS = "-m-3 rounded-lg p-3";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  FORM_STEP_CLASS,
  FormStepsContext,
  InsideFormStepContext,
  formStepAttrs,
} from "./form-steps-context";

/*
  FORM STEPS — a side-sheet form read as one long scroll, with a list of its
  steps in a column on the left (Pavan, 2026-10-05; tried on Create Delivery
  Order, then made the default for every form).

  HOW A STEP COMES TO EXIST. Inside a stepped sheet every top-level
  `SheetSection` is a step, named by its title — so a form gets the list
  without being rewritten. A form that wants several sections under one name
  wraps them in `FormStep`; the sections inside then stop being steps of their
  own.

  THE LIST IS READ FROM THE PAGE, not declared. Sections come and go with the
  record's state (a locked order shows facts, a movement shows its asset), and
  a list kept beside the form would drift from it. `FormStepsNav` watches the
  form and lists what is actually there, in the order it is drawn.

  THE LOOK FOLLOWS. Group headings lose their band and dim, tables keep their
  rim and nothing else — see `SheetSection`.
*/

/** Several sections under one step name. Outside a stepped sheet, nothing. */
export function FormStep({
  label,
  className,
  children,
}: {
  label: string;
  className?: string;
  children: React.ReactNode;
}) {
  const stepped = React.useContext(FormStepsContext);
  if (!stepped) return <>{children}</>;
  return (
    <section
      {...formStepAttrs(label)}
      className={cn("flex shrink-0 flex-col gap-10", FORM_STEP_CLASS, className)}
    >
      <InsideFormStepContext.Provider value>{children}</InsideFormStepContext.Provider>
    </section>
  );
}

const SPY_OFFSET = 96;

/** Height of whatever the form pins over its own top (`data-form-sticky`). */
function pinnedHeight(port: HTMLElement) {
  let h = 0;
  port.querySelectorAll<HTMLElement>("[data-form-sticky]").forEach((el) => {
    h += el.getBoundingClientRect().height;
  });
  return h;
}

/**
 * The step list. `formRef` is the form's own scroll column — the list reads
 * the steps from it, follows its scroll, and scrolls it when a step is
 * pressed. `onCount` reports how many steps there are, so the sheet can drop
 * the column when there is nothing to list.
 */
/**
 * SCROLL A SHEET'S FORM TO ONE OF ITS STEPS and mark it once with a quiet
 * fill — the step column's press, shared so another control can do the same
 * (the 3PL order sheet's stage track, Pavan 2026-10-23). `port` is the form's
 * scroller, `el` the `[data-form-step]` section.
 */
export function travelToStep(port: HTMLElement, el: HTMLElement, done?: () => void) {
  const from = port.scrollTop;
  const target = Math.max(
    0,
    Math.min(
      from + el.getBoundingClientRect().top - port.getBoundingClientRect().top - 16 - pinnedHeight(port),
      port.scrollHeight - port.clientHeight
    )
  );
  const started = performance.now();
  const frame = (now: number) => {
    const t = Math.min((now - started) / 320, 1);
    port.scrollTop = from + (target - from) * (1 - Math.pow(1 - t, 3));
    if (t < 1) {
      requestAnimationFrame(frame);
      return;
    }
    done?.();
    el.classList.remove("fp-attention-fill-subtle");
    void el.offsetWidth;
    el.classList.add("fp-attention-fill-subtle");
    window.setTimeout(() => el.classList.remove("fp-attention-fill-subtle"), 800);
  };
  requestAnimationFrame(frame);
}

export function FormStepsNav({
  formRef,
  onCount,
  footer,
  headerAction,
}: {
  formRef: React.RefObject<HTMLDivElement | null>;
  onCount?: (n: number) => void;
  /** A control at the end of the progress bar's row — e.g. form settings. */
  headerAction?: React.ReactNode;
  /** Pinned to the foot of the column — the sheet's pending strip. */
  footer?: React.ReactNode;
}) {
  const [labels, setLabels] = React.useState<string[]>([]);
  const [at, setAt] = React.useState(0);
  const travelling = React.useRef(false);

  const stepEls = React.useCallback(
    () =>
      Array.from(
        formRef.current?.querySelectorAll<HTMLElement>("[data-form-step]") ?? []
      ),
    [formRef]
  );

  /* WHAT IS ON THE PAGE, re-read whenever the form changes shape. A passive
     effect, not a layout one: the form column is a later sibling, and its ref
     is not attached yet when this column's layout effects run. */
  React.useEffect(() => {
    const port = formRef.current;
    if (!port) return;
    let last = "";
    const read = () => {
      const next = stepEls().map((el) => el.dataset.formStep ?? "");
      const key = next.join("\u0000");
      if (key === last) return;
      last = key;
      setLabels(next);
      onCount?.(next.length);
    };
    read();
    const mo = new MutationObserver(read);
    mo.observe(port, {
      childList: true,
      subtree: true,
      attributes: true,
      attributeFilter: ["data-form-step"],
    });
    return () => mo.disconnect();
  }, [formRef, stepEls, onCount]);

  /* THE LIST FOLLOWS THE SCROLL: the current step is the last one whose top
     has reached the top of the form. At the very bottom, it is the last. */
  React.useEffect(() => {
    const port = formRef.current;
    if (!port) return;
    const onScroll = () => {
      if (travelling.current) return;
      const top = port.getBoundingClientRect().top;
      const pin = pinnedHeight(port);
      const els = stepEls();
      let i = 0;
      els.forEach((el, n) => {
        if (el.getBoundingClientRect().top - top <= SPY_OFFSET + pin) i = n;
      });
      if (port.scrollTop + port.clientHeight >= port.scrollHeight - 4)
        i = els.length - 1;
      setAt(Math.max(0, i));
    };
    onScroll();
    port.addEventListener("scroll", onScroll, { passive: true });
    return () => port.removeEventListener("scroll", onScroll);
  }, [formRef, stepEls, labels]);

  /* A PRESS SCROLLS TO THE STEP, up or down, then marks it with a quiet grey
     fill, once. Driven frame by frame because the sheet's scroll lock cancels
     the browser's smooth scroll (see `attend` in PendingStrip). */
  const go = (i: number) => {
    const port = formRef.current;
    const el = stepEls()[i];
    if (!port || !el) return;
    setAt(i);
    travelling.current = true;
    travelToStep(port, el, () => (travelling.current = false));
  };

  const current = Math.min(at, Math.max(labels.length - 1, 0));

  return (
    <nav
      aria-label="Form steps"
      className="flex min-h-0 w-56 shrink-0 flex-col gap-4 overflow-auto border-r border-border p-4"
    >
      <div className="flex flex-col gap-2">
        <span className="text-xs text-muted-foreground tabular-nums">
          Step {current + 1} of {labels.length}
        </span>
        {/* THE ACTION ENDS THE BAR'S ROW, centred on it. */}
        <div className="flex items-center gap-2">
          <div className="h-1 flex-1 overflow-hidden rounded-full bg-muted">
            <div
              className="h-full rounded-full bg-foreground transition-[width]"
              style={{ width: `${((current + 1) / Math.max(labels.length, 1)) * 100}%` }}
            />
          </div>
          {headerAction && (
            <div className="flex h-1 shrink-0 items-center">{headerAction}</div>
          )}
        </div>
      </div>
      <ol className="flex flex-col gap-0.5">
        {labels.map((label, i) => {
          const on = i === current;
          return (
            <li key={`${label}-${i}`}>
              {/* QUIETER (Pavan, 2026-10-05): 13px type, a bare number 8px from its name,
                  flush with the column's left edge (no inset of its own), no
                  disc and no fill. The step you are on is told by colour alone
                  — selection ink (orange) on its number and name; the rest are
                  grey, the numbers lighter than the names. */}
              <button
                type="button"
                aria-current={on ? "step" : undefined}
                onClick={() => go(i)}
                className={cn(
                  "group/step flex w-full items-baseline gap-2 rounded-sm py-1.5 text-left text-[13px] outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50",
                  on
                    ? "font-medium text-selected-foreground dark:text-brand"
                    : "text-muted-foreground hover:text-foreground"
                )}
              >
                <span
                  className={cn(
                    "shrink-0 tabular-nums",
                    !on && "text-muted-foreground/60 group-hover/step:text-foreground"
                  )}
                >
                  {i + 1}
                </span>
                <span className="truncate">{label}</span>
              </button>
            </li>
          );
        })}
      </ol>
      {/* THE PENDING STRIP, at the foot of the column it steers. */}
      {footer && (
        <div className="@container mt-auto border-t border-border pt-3">{footer}</div>
      )}
    </nav>
  );
}

/**
 * A sheet's body as a stepped form: the step column, then the form's own
 * scroll. Drop-in for the body `div` of any side sheet. `onShownChange` says
 * whether the column is showing — a sheet takes the full width while it is.
 * `footer` (the pending strip) sits at the foot of the column while it shows;
 * while it does not, the sheet keeps the strip wherever it had it.
 */
export function SteppedFormBody({
  children,
  footer,
  footerClassName,
  top,
  onShownChange,
  stepsAction,
  hideColumn = false,
}: {
  children: React.ReactNode;
  /**
   * Keep the stepped form's look (plain group headings, one long scroll) but
   * do not show the step column. The column is archived, not removed — see
   * docs/ds/ui/archive/step-column.md.
   */
  hideColumn?: boolean;
  /** Passed to the step column's header row — see `FormStepsNav`. */
  stepsAction?: React.ReactNode;
  /**
   * THE PENDING BAR (Pavan, 2026-10-05): pinned under the form column, above
   * the sheet footer — not in the step column. Sheets pass it only once the
   * primary has been pressed with something still missing.
   */
  footer?: React.ReactNode;
  /** Insets the bar — e.g. to stop short of a right-hand rail. */
  footerClassName?: string;
  /**
   * A band over the FORM column only — the stage track. It starts where the
   * form starts, not over the step column, and stays put while the form
   * scrolls.
   */
  top?: React.ReactNode;
  onShownChange?: (shown: boolean) => void;
}) {
  const formRef = React.useRef<HTMLDivElement>(null);
  const [count, setCount] = React.useState(0);
  const shown = count >= 2 && !hideColumn;
  React.useEffect(() => {
    onShownChange?.(shown);
  }, [shown, onShownChange]);
  return (
    <FormStepsContext.Provider value>
      <div className="flex min-h-0 flex-1">
        {/* MOUNTED WHILE HIDDEN so it can count the steps; the form column
            keeps its place in the tree either way. */}
        <div className={cn("flex min-h-0", !shown && "hidden")}>
          <FormStepsNav formRef={formRef} onCount={setCount} headerAction={stepsAction} />
        </div>
        <div className="flex min-h-0 min-w-0 flex-1 flex-col">
          {top && (
            <div className="shrink-0 border-b border-border px-4">{top}</div>
          )}
          <div
            ref={formRef}
            className="flex min-h-0 min-w-0 flex-1 flex-col gap-10 overflow-auto p-4"
          >
            {children}
          </div>
          {footer && (
            <div
              className={cn(
                /* THE DS SOFT CAUTION BANNER, made opaque over the sheet — it
                   appears because a press was refused, so it has to be seen. */
                "shrink-0 border-t border-fp-banner-accent-caution/30 bg-[color-mix(in_oklab,var(--fp-banner-accent-caution)_10%,var(--color-popover))] px-4 py-2.5",
                footerClassName
              )}
            >
              {footer}
            </div>
          )}
        </div>
      </div>
    </FormStepsContext.Provider>
  );
}

import * as React from "react";
import { CircleAlert, Info, Minus } from "lucide-react";
import { cn } from "@/lib/utils";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Steps, type StepItem } from "@/components/ui/steps";
import {
  FORM_STEP_CLASS,
  FormStepsContext,
  InsideFormStepContext,
  formStepAttrs,
} from "./form-steps-context";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";

/* Shared building blocks for the Side Sheet variants (Figma 27610:58293). */

/** Section = muted group heading + fields. */
export function SheetSection({
  title,
  action,
  note,
  variant: variantProp = "card",
  flush = false,
  hanging,
  bodyClassName,
  headingClassName,
  children,
  className,
  id,
}: {
  title: string;
  /**
   * `card` — the default — draws the section as a bordered block with its
   * title in a tinted header band. A sheet is a stack of questions about
   * different things, and gaps alone were carrying the whole job of saying
   * where one subject ended and the next began; at 40px they did it only for
   * as long as nothing in a section grew. The border says it at any length.
   *
   * `plain` is the old heading-over-fields form, for the handful of places
   * that are a single continuous list rather than a set of groups.
   */
  variant?: "plain" | "card" | "outline";
  /**
   * Classes for the heading text — for a form that sets its group headings at
   * a different step of the type scale.
   */
  headingClassName?: string;
  /**
   * Card variant only: drop the body's padding so a single child can run edge
   * to edge under the header band.
   *
   * FOR A SECTION THAT IS ONE TABLE. A table already draws a border, a header
   * band and a rule between every row; set inside a padded card it became a
   * box in a box, with 16px of nothing between two lines doing the same job
   * and the table's own header band sitting a hair inside the card's. Flush,
   * the card's border IS the table's border and there is one edge instead of
   * two. The child owns its own insets — anything that is not the table (an
   * Add row, a footnote) has to bring its own padding and its own top rule.
   */
  flush?: boolean;
  /**
   * A control that HANGS OFF THE CARD'S BOTTOM-LEFT, outside it.
   *
   * FOR THE ADD ON A TABLE. The card's bottom-left corner squares so the two
   * join, and the control continues the table's last row rather than sitting
   * on a full-width band inside the card — a band draws a rule across the
   * whole card to carry one small act, and reads as an empty extra row of the
   * table. (Pavan, 2026-09-22.)
   */
  hanging?: React.ReactNode;
  /**
   * Classes for the BODY, not the card — for a section that has to fill the
   * height it is given rather than wrap its content. A composer's message box
   * is the case: it should run to the bottom of the sheet, and only the body
   * can be told to grow.
   */
  bodyClassName?: string;
  /**
   * Controls that act on the SECTION rather than on one field — "Add asset",
   * "Refresh". They sit on the heading row, right-aligned, because a control
   * that owns a whole section has no field to belong to.
   */
  action?: React.ReactNode;
  /** An explainer beside the heading — typically `SheetSectionNote`. */
  note?: React.ReactNode;
  children: React.ReactNode;
  className?: string;
  /**
   * An anchor on the section, for a caller that has to bring one section into
   * view — a list's footer action that opens a record AT the part it is about.
   */
  id?: string;
}) {
  /* SECTION RHYTHM — 40 / 16. The gap between sections is 40px (owned by the
     sheet body); the gap between a section's title and its content is 16px. The
     outer gap being 2.5x the inner is what makes a heading read as belonging to
     the block beneath it rather than floating between two blocks. At 20 the
     title sat almost equidistant from both; below 16 it welds to the first
     field and the whole boundary rests on the 40.

     THE 16 IS MEASURED FROM THE TITLE, and that is the whole reason the heading
     row has no height of its own. It used to be `min-h-7` (28px) around a 20px
     line, and `items-center` split the spare 8px evenly — so what anyone could
     actually see between the words and the content was 20px, and 22px in a
     section whose heading also carried a 32px action button. The rule said 16
     and the screen said 20: the row was padding itself and calling it rhythm.

     An ACTION taller than the title now hangs off the line instead of pushing
     the content down: its wrapper is fixed at the title's own 20px and centres
     a taller child, which overflows the box without growing it. That holds for
     any control put there — a 32px button, a switch, a picker — so the 16
     cannot drift again the next time a section gains an action. */
  /* IN A STEPPED FORM (see `form-steps`) the card's band goes: a section
     that is fields becomes `plain`, a section that is a table keeps its rim as
     `outline`. A top-level section is also a step, named by its title. */
  const stepped = React.useContext(FormStepsContext);
  const insideStep = React.useContext(InsideFormStepContext);
  const isStep = stepped && !insideStep;
  const variant =
    stepped && variantProp === "card"
      ? flush || hanging
        ? "outline"
        : "plain"
      : variantProp;
  const stepAttrs = isStep ? formStepAttrs(title) : {};
  if (isStep) {
    children = (
      <InsideFormStepContext.Provider value>{children}</InsideFormStepContext.Provider>
    );
  }

  const heading = (
    <div className="flex items-center justify-between gap-4">
      <div className="flex items-center gap-1.5">
        <h3
          className={cn(
            "text-sm font-semibold text-muted-foreground",
            /* Sub-heading size, dimmed so the fields lead. */
            stepped && "text-base font-medium",
            headingClassName
          )}
        >
          {title}
        </h3>
        {/* Sits WITH the heading, not after the content: an explanation of
            how a section works belongs where the section is named, and on
            demand rather than as a paragraph everyone reads once. */}
        {note}
      </div>
      {action && (
        <div className="flex h-5 shrink-0 items-center justify-end">{action}</div>
      )}
    </div>
  );

  if (variant === "outline") {
    /* `outline` — the plain heading OVER an outlined box, no band. For a form
       whose group headings carry no fill but whose tables keep their rim.
       The box takes `flush` and `hanging` exactly as the card does. The rim
       is the data table's `--border`, per the DS table stroke. */
    const box = (
      <div
        className={cn(
          "flex shrink-0 flex-col overflow-hidden rounded-lg border border-border",
          !flush && "gap-4 p-4",
          hanging && "rounded-bl-none",
          bodyClassName
        )}
      >
        {children}
      </div>
    );
    return (
      <section
        id={id}
        {...stepAttrs}
        className={cn("flex shrink-0 flex-col gap-4", isStep && FORM_STEP_CLASS, className)}
      >
        {heading}
        {hanging ? (
          <div className="flex flex-col">
            {box}
            <div className="flex w-full items-center justify-between gap-4">
              {hanging}
            </div>
          </div>
        ) : (
          box
        )}
      </section>
    );
  }

  if (variant === "card") {
    /* THE HEADING MOVES INTO A BAND, because a title inside a bordered block
       that shares the block's fill reads as the first row of content rather
       than as the name of what follows.

       The 16px title→content rhythm the plain variant measures so carefully is
       not needed here: the band's own edge is the separation, and it holds at
       any section length — which is the thing a 40px gap could not do. */
    const card = (
      <section
        id={hanging ? undefined : id}
        /* `shrink-0` IS LOAD-BEARING, not tidiness. The sheet body is a flex
           column, and `overflow-hidden` switches a flex item's automatic
           minimum size from its content to zero — so without this the whole
           card collapses to its own 2px of border. */
        className={cn(
          /* THE RIM IS `--fp-outline-1`, NOT `--border` (Pavan, 2026-09-22).
             The DS's stroke table has said so all along — outline-1 is "a
             card's own rim" and `--border` is "a structural divider" — and
             this card was drawing the divider weight round its outside, which
             is why a card sat heavier on the page than the lines inside it.
             In DARK the two tokens carry the same value, so this is a
             light-mode correction only. */
          "shrink-0 overflow-hidden rounded-lg border border-fp-outline-1",
          /* SQUARED WHERE THE HANGING CONTROL JOINS, so the two read as one
             shape rather than a rounded box with a tab floating under it. */
          hanging && "rounded-bl-none",
          /* THE CALLER'S CLASSES GO ON WHICHEVER ELEMENT IS THE OUTER ONE.
             With something hanging, that is the wrapper below, not this —
             `lg:col-span-3` landing here put the SECTION inside a grid item
             that was still one column wide, so a section could be told to take
             three columns and silently take one. (Found 2026-09-22, on the
             Documents table.) */
          !hanging && className
        )}
      >
        <div className="border-b border-border bg-fp-surface-1a px-4 py-2.5">
          {heading}
        </div>
        <div
          className={cn(
            "flex flex-col",
            !flush && "gap-4 p-4",
            bodyClassName
          )}
        >
          {children}
        </div>
      </section>
    );

    /* THE WRAPPER OWNS THE `shrink-0` AND THE ID once there is something
       hanging: the card and its tab are one block in the sheet's stack, and
       the body's 40px gap has to fall after the tab rather than between the
       two. */
    return hanging ? (
      <div id={id} className={cn("flex shrink-0 flex-col", className)}>
        {card}
        {/* THE HANGING ROW runs the card's width so a second thing can sit at
            its right end — the add on the left, a flag about the whole unit on
            the right. With one child `justify-between` leaves it on the left,
            which is where a lone add belongs. */}
        <div className="flex w-full items-center justify-between gap-4">
          {hanging}
        </div>
      </div>
    ) : (
      card
    );
  }

  return (
    <section
      id={id}
      {...stepAttrs}
      className={cn("flex flex-col gap-4", isStep && FORM_STEP_CLASS, className)}
    >
      {heading}
      {children}
    </section>
  );
}

/**
 * The card's own insets, given back to one child of a `flush` section.
 *
 * A flush section is for a table, and a section is rarely ONLY a table — a
 * banner above it, a switch below. Those still need the 16px the body gave up,
 * and they need it individually rather than as a blanket, because the table
 * between them must keep running to the card's edge. Add `border-t`/`border-b`
 * at the call site where the inset meets the table: the rule belongs to the
 * boundary, and only the call site knows which side it is on.
 */
export function SheetSectionInset({
  children,
  className,
}: {
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-col gap-4 p-4", className)}>{children}</div>
  );
}

/**
 * The remove control for an OPTIONAL section — the one that takes a section
 * that has been turned on back to its "Add …" box.
 *
 * A MINUS, NOT A BIN. A bin says a record is about to be destroyed, and this
 * destroys nothing: the section collapses to the CTA it came from and can be
 * added again in one click. The two icons look alike at 16px and mean opposite
 * things about whether the click can be taken back, so the optional-section
 * control never wears the bin — that stays on the ROW delete inside a table,
 * where a row really does go.
 *
 * QUIET UNTIL REACHED FOR. Emptying a section that was optional in the first
 * place should not compete with the table for attention, so it is a muted icon
 * that comes to full contrast and slides its label out on hover or focus. The
 * label is what makes it safe — a bare glyph beside a table of rows reads as
 * though it might remove a row.
 *
 * IT ASKS ONLY WHEN THERE IS SOMETHING TO LOSE. `hasContent` is the caller's
 * answer to "has anyone typed anything in here yet" — with rows filled the
 * click opens a confirm, and on an untouched section it just closes it. A
 * dialog over an empty table teaches people to dismiss dialogs without reading
 * them, which is exactly the habit that makes the one that matters useless.
 */
export function SheetSectionRemove({
  label,
  hasContent,
  onClick,
}: {
  /** Names what goes, e.g. "Remove peripherals". Shown on hover and to AT. */
  label: string;
  /**
   * True when the section holds something a person put there. Only then is
   * removal worth confirming — the caller knows what "filled in" means for its
   * own rows, so it decides rather than this component guessing.
   */
  hasContent?: boolean;
  onClick: () => void;
}) {
  const trigger = (
    <button
      type="button"
      onClick={hasContent ? undefined : onClick}
      aria-label={label}
      className="group/rm flex h-8 items-center gap-1.5 rounded-md px-2 text-muted-foreground outline-none transition-colors hover:bg-accent hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50"
    >
      <Minus className="size-4 shrink-0" />
      <span className="max-w-0 overflow-hidden text-sm whitespace-nowrap opacity-0 transition-[max-width,opacity] duration-200 group-hover/rm:max-w-40 group-hover/rm:opacity-100 group-focus-visible/rm:max-w-40 group-focus-visible/rm:opacity-100">
        {label}
      </span>
    </button>
  );

  if (!hasContent) return trigger;

  return (
    <AlertDialog>
      <AlertDialogTrigger asChild>{trigger}</AlertDialogTrigger>
      <AlertDialogContent>
        <AlertDialogHeader>
          {/* The button's own label, as a question — the dialog answers the
              click that opened it rather than restating the section's name. */}
          <AlertDialogTitle>{label}?</AlertDialogTitle>
          <AlertDialogDescription>
            Everything added here will be erased. This cannot be undone.
          </AlertDialogDescription>
        </AlertDialogHeader>
        <AlertDialogFooter>
          <AlertDialogCancel>Cancel</AlertDialogCancel>
          <AlertDialogAction variant="destructive" onClick={onClick}>
            Remove
          </AlertDialogAction>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  );
}

/** Field = label + control + helper text. */
export function SheetField({
  label,
  description,
  required,
  children,
  className,
}: {
  /**
   * A node, not just a string: a field's label row sometimes carries a control
   * that acts on the whole field — an "Invite" beside a picker — and that
   * control belongs on the label row rather than trailing the field's body.
   */
  label?: React.ReactNode;
  description?: string;
  /** Marks the label with the destructive asterisk the DS forms already use. */
  required?: boolean;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-col gap-1.5", className)}>
      {label && (
        <label className="block text-sm font-medium text-foreground">
          {label}
          {required && <span className="text-destructive"> *</span>}
        </label>
      )}
      {/* HELPER TEXT IS PART OF THE CONTROL, 4px under it — not the next thing
          down the form. At the field gap it floats between two controls and gets
          read as a label for the one below. Label→control keeps the field's own
          rhythm; control→helper is always 4px. */}
      <div className="flex flex-col gap-1">
        {children}
        {description && (
          <p className="text-xs text-muted-foreground">{description}</p>
        )}
      </div>
    </div>
  );
}

/** The top-of-body alert banner shared by every variant. */
export function InfoAlert() {
  return (
    <Alert>
      <CircleAlert />
      <AlertTitle>Alert Title</AlertTitle>
      <AlertDescription>This is an alert description.</AlertDescription>
    </Alert>
  );
}

/**
 * The "why does this section behave this way" explainer, on demand.
 *
 * A paragraph under a section is read once and then permanently in the way; the
 * rule it states is needed at the moment someone WONDERS, which is rarely the
 * moment they first arrive. On CLICK rather than hover, because hover cannot be
 * reached by touch and a tooltip that appears while you are aiming at something
 * else is worse than no tooltip.
 *
 * Deliberately NARROW. Explanations set to the full width of a sheet become one
 * long line that has to be tracked back across; a few short lines are read at a
 * glance.
 */
export function SheetSectionNote({
  label = "About this section",
  children,
}: {
  /** Names the button for assistive tech. */
  label?: string;
  children: React.ReactNode;
}) {
  return (
    <Popover>
      <PopoverTrigger asChild>
        <button
          type="button"
          aria-label={label}
          className="flex size-5 items-center justify-center rounded-full text-muted-foreground outline-none transition-colors hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring/50 data-[state=open]:text-foreground"
        >
          <Info className="size-4" />
        </button>
      </PopoverTrigger>
      <PopoverContent align="start" className="w-64 text-xs leading-relaxed">
        {children}
      </PopoverContent>
    </Popover>
  );
}

/**
 * The sheet's step strip — the DS `Steps` control, sized and spaced for a
 * sheet header.
 *
 * A THIN WRAPPER ON PURPOSE. It exists so a sheet does not have to remember the
 * height and the border the header strip needs, not to be a second stepper: the
 * states, the numbering, the connector and the disabled-with-a-reason behaviour
 * are all `Steps`.
 */
export function SheetSteps({
  steps,
  value,
  onValueChange,
  tone,
  variant,
}: {
  steps: StepItem[];
  value: string;
  onValueChange: (next: string) => void;
  tone?: "brand" | "accent" | "neutral";
  variant?: "track" | "rings";
}) {
  return (
    <Steps
      tone={tone}
      variant={variant}
      steps={steps}
      value={value}
      onValueChange={onValueChange}
      className="my-2.5"
    />
  );
}

import * as React from "react";
import { AlertDialog as AlertDialogPrimitive } from "radix-ui";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";

